import sys, csv, re, math, statistics as st
from collections import defaultdict, Counter

info_p, gen_p = sys.argv[1], sys.argv[2]
def read_tsv(p):
    with open(p, encoding="utf-8") as f:
        r = list(csv.reader(f, delimiter="\t"))
    return r[0], r[1:]
ih, ir = read_tsv(info_p); gh, gr = read_tsv(gen_p)
I = {row[0]: dict(zip(ih, row)) for row in ir}
G = {row[0]: {g: float(v) for g, v in zip(gh[1:], row[1:])} for row in gr}
genera = gh[1:]
T = ["0W", "2W", "4W"]
by = {t: sorted([s for s in I if I[s]["timepoint"] == t], key=lambda s: I[s]["subject"]) for t in T}
mean = lambda xs: sum(xs)/len(xs)
M = {t: {g: mean([G[s][g] for s in by[t]]) for g in genera} for t in T}
prev = {t: {g: sum(1 for s in by[t] if G[s][g] > 0)/25 for g in genera} for t in T}

# 1) genera present essentially only in the 0W run (objective rule)
batch = [g for g in genera if g != "Unassigned" and M["0W"][g] >= 0.1
         and M["0W"][g] >= 10*max(M["2W"][g], M["4W"][g], 1e-9)]
batch.sort(key=lambda g: -M["0W"][g])
print("0W-run-specific genera (0W mean>=0.1%, >=10x later):", len(batch))
for g in batch:
    print(f"  {g:32s} 0W {M['0W'][g]:6.2f}% (in {prev['0W'][g]*25:.0f}/25)  2W {M['2W'][g]:5.2f}% ({prev['2W'][g]*25:.0f}/25)  4W {M['4W'][g]:5.2f}% ({prev['4W'][g]*25:.0f}/25)")
bsum = {s: sum(G[s][g] for g in batch) for s in G}
for t in T:
    xs = [bsum[s] for s in by[t]]
    print(f"  sum of these at {t}: median {st.median(xs):.1f}%  [{min(xs):.1f}, {max(xs):.1f}]")

# reverse: genera only in later runs
rev = [g for g in genera if g != "Unassigned" and max(M["2W"][g], M["4W"][g]) >= 0.5 and M["0W"][g] < 0.1*max(M["2W"][g], M["4W"][g])]
print("\ngenera near-absent at 0W but >=0.5% later:", [(g, round(M['0W'][g],2), round(M['2W'][g],2), round(M['4W'][g],2)) for g in rev])

# 2) how constant are batch taxa across the 25 different people at 0W? (ratio Wolbachia/Sphingomonas)
r = [G[s]["Wolbachia"]/G[s]["Sphingomonas"] for s in by["0W"]]
cv = lambda xs: st.pstdev(xs)/mean(xs)
print(f"\n0W Wolbachia/Sphingomonas ratio: median {st.median(r):.2f} range [{min(r):.2f},{max(r):.2f}] CV {cv(r):.2f}")
r2 = [G[s]["Akkermansia"]/G[s]["Wolbachia"] for s in by["0W"]]
print(f"0W Akkermansia/Wolbachia ratio: median {st.median(r2):.3f} range [{min(r2):.3f},{max(r2):.3f}] CV {cv(r2):.2f}")
cs0 = [G[s]["Cutibacterium"]+G[s]["Staphylococcus"] for s in by["0W"]]
print(f"0W Cuti+Staph CV {cv(cs0):.2f} (vs batch-sum CV {cv([bsum[s] for s in by['0W']]):.2f})")
# correlation batch-sum vs Cuti+Staph at 0W
def pear(a, b):
    ma, mb = mean(a), mean(b)
    return sum((x-ma)*(y-mb) for x, y in zip(a, b))/math.sqrt(sum((x-ma)**2 for x in a)*sum((y-mb)**2 for y in b))
def rk(a):
    o = sorted(range(len(a)), key=lambda i: a[i]); r = [0]*len(a)
    for k, i in enumerate(o): r[i] = k
    return r
print(f"0W Spearman(batch-sum, Cuti+Staph) = {pear(rk([bsum[s] for s in by['0W']]), rk(cs0)):+.2f}")

# 3) renormalise without batch genera (and sensitivity: also without Unassigned)
def renorm(s, drop):
    tot = 100 - sum(G[s][g] for g in drop)
    return {g: G[s][g]*100/tot for g in genera if g not in drop}
def wil(d):
    d = [x for x in d if x != 0]; n = len(d)
    o = sorted(range(n), key=lambda i: abs(d[i])); ranks = [0]*n; i = 0
    while i < n:
        j = i
        while j+1 < n and abs(d[o[j+1]]) == abs(d[o[i]]): j += 1
        for k in range(i, j+1): ranks[o[k]] = (i+j)/2+1
        i = j+1
    Wp = sum(rk for rk, x in zip(ranks, d) if x > 0)
    z = (Wp - n*(n+1)/4)/math.sqrt(n*(n+1)*(2*n+1)/24)
    return z, math.erfc(abs(z)/math.sqrt(2))
for label, drop in [("drop 0W-run genera", set(batch)), ("drop 0W-run genera + Unassigned", set(batch) | {"Unassigned"})]:
    R = {s: renorm(s, drop) for s in G}
    print(f"\n=== renormalised: {label} ===")
    for g in ["Cutibacterium", "Staphylococcus"]:
        for t in T:
            xs = [R[s][g] for s in by[t]]
            print(f"  {g:15s} {t}: median {st.median(xs):6.2f}  mean {mean(xs):6.2f}")
        for a, b in [("0W", "2W"), ("0W", "4W"), ("2W", "4W")]:
            A = {I[s]['subject']: R[s][g] for s in by[a]}; B = {I[s]['subject']: R[s][g] for s in by[b]}
            d = [B[k]-A[k] for k in sorted(A)]
            z, p = wil(d)
            print(f"     {a}->{b}: median diff {st.median(d):+6.2f}  up {sum(x>0 for x in d)}/25  Wilcoxon z={z:+.2f} p~{p:.2g}")
    # log-ratio Cuti / Staph (invariant to any dilution)
    if label.endswith("genera"):
        pass

# 4) subject identity: is a person's 0W sample closer to her own 2W/4W than to others'?
def bc(a, b, keep):
    num = sum(abs(a[g]-b[g]) for g in keep); den = sum(a[g]+b[g] for g in keep)
    return num/den
keep = [g for g in genera if g not in set(batch) and g != "Unassigned"]
R = {s: renorm(s, set(batch) | {"Unassigned"}) for s in G}
def ident(ta, tb):
    hits = 0; own = []; oth = []
    A = {I[s]['subject']: s for s in by[ta]}; B = {I[s]['subject']: s for s in by[tb]}
    for k in A:
        ds = {k2: bc(R[A[k]], R[B[k2]], keep) for k2 in B}
        best = min(ds, key=ds.get); hits += (best == k)
        own.append(ds[k]); oth += [v for k2, v in ds.items() if k2 != k]
    return hits, mean(own), mean(oth)
print("\n=== subject re-identification (Bray-Curtis, cleaned) ===")
for a, b in [("0W", "2W"), ("0W", "4W"), ("2W", "4W")]:
    h, o, x = ident(a, b)
    print(f"  {a} vs {b}: own-sample nearest {h}/25 (chance ~1)  mean BC own {o:.2f} vs others {x:.2f}")

# 5) depth / richness by timepoint
print()
for c in ["read_count", "read_depth_final", "Observed", "Shannon", "n_genus_detected"]:
    print(c, {t: round(st.median([float(I[s][c]) for s in by[t]]), 2) for t in T})

